            //
            aIngress = (RotL64(aFuseLaneB[((aIndex + 19748U)) & S_BLOCK1], 38U) ^ RotL64(aWaterLaneD[((aIndex + 18422U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aEarthLaneC[((aIndex + 17615U)) & S_BLOCK1], 23U) ^ RotL64(aSource[((S_BLOCK1 - aIndex + 20226U)) & S_BLOCK1], 53U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 23793U)) & S_BLOCK1], 19U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 17578U)) & S_BLOCK1], 28U));
            aCross ^= RotL64(pSnowLaneA[((aIndex + 18600U)) & S_BLOCK1], 41U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 52U) + RotL64(aCross, 23U)) ^ (RotL64(aCarry, 35U) ^ RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterE = (aWandererA + RotL64(aScatter, 51U)) + 0x9F5EE79EB9421A73ULL;
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 6U)) + RotL64(aCarry, 23U)) + 0x64F76B7C77D51593ULL;
            aOrbiterC = (aWandererK + RotL64(aIngress, 29U)) + 0x93A3F1C14BE085ADULL;
            aOrbiterB = (((aWandererB + RotL64(aCross, 43U)) + RotL64(aCarry, 47U)) + 0x9241C52464212203ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 57U)) + 0x1419D230D7E77AF7ULL) + aTwistOrbiterAssignSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterI = (aWandererC + RotL64(aIngress, 35U)) + 0xFBA874498173D9F3ULL;
            aOrbiterD = ((aWandererF + RotL64(aScatter, 19U)) + RotL64(aCarry, 3U)) + 0x986334984BEF1947ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xF6354C670BE4C56DULL) + aTwistOrbiterUpdateSaltE[((aIndex + 12U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0x899A2BF94222E914ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xE0DA65F33F199083ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x6A6B5463C61DAF08ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x706FEAA49F36E69BULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC0E9F4DFC6F846FDULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x4554178CD50EC48EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xC272C9F65C23102BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF62F286B3BD6DB6BULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x2E4EF392048214D0ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x5C886856795F4D05ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8382B496062884A1ULL), 35U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x64E177618352354FULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x999F734134DEBAF5ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xDA994F6CE84A2455ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x4919B1554C968CD3ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x7BF652778B5015DEULL;
            aOrbiterB = RotL64((aOrbiterB * 0x428C4C81DB2F4705ULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x5D4E86D02A568179ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x7DD74C4185359114ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 9U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x9DA4A03CA30EA451ULL), 43U);
            //
            aIngress = RotL64(aOrbiterK, 3U) ^ aOrbiterI;
            aIngress = aIngress + (RotL64(aOrbiterJ, 27U) ^ aOrbiterB);
            aIngress = aIngress + (RotL64(aOrbiterC, 47U) ^ aOrbiterD);
            aIngress = aIngress + RotL64(aOrbiterE, 10U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 43U) + aOrbiterB) + RotL64(aOrbiterC, 53U));
            aWandererD = aWandererD + ((((RotL64(aIngress, 3U) + RotL64(aOrbiterB, 41U)) + aOrbiterD) + RotL64(aCarry, 5U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 35U) + aOrbiterB) + RotL64(aOrbiterI, 24U));
            aWandererF = aWandererF + ((((RotL64(aCross, 23U) + RotL64(aOrbiterK, 13U)) + aOrbiterC) + RotL64(aCarry, 27U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 24U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 29U) + aOrbiterI) + RotL64(aOrbiterJ, 35U));
            aWandererK = aWandererK + ((RotL64(aCross, 13U) + RotL64(aOrbiterE, 47U)) + aOrbiterC);
