            //
            aScatter = (RotL64(aCarry, 23U) ^ RotL64(aIngress, 43U)) ^ (RotL64(aPrevious, 11U) + RotL64(aCross, 56U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = ((aWandererC + RotL64(aScatter, 57U)) + RotL64(aCarry, 5U)) + 0x4107585ACF5C0E1AULL;
            aOrbiterI = ((aWandererE + RotL64(aIngress, 5U)) + 0x3A596B160D7DA73BULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterJ = (aWandererF + RotL64(aCross, 13U)) + 0xC19335B9DB3914C4ULL;
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 51U)) + RotL64(aCarry, 53U)) + 0x23F971A15EEBE8A7ULL;
            aOrbiterK = (aWandererI + RotL64(aScatter, 22U)) + 0x03A5C4975D968CE1ULL;
            aOrbiterF = ((aWandererD + RotL64(aCross, 37U)) + RotL64(aCarry, 21U)) + 0xBDA95F2C43D0C095ULL;
            aOrbiterB = ((aWandererA + RotL64(aPrevious, 43U)) + 0x885A9267184B9C12ULL) + aTwistOrbiterAssignSaltC[((aIndex + 24U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x41CBEA14AA995D5EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xF19DB80C8673BE4EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x166083B6E80AE505ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x2DC39ECDA884227BULL) + aTwistOrbiterUpdateSaltD[((aIndex + 22U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x195D707582558DD6ULL;
