            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xE5F50B22B5167514ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x6E3D14E83799229DULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA825A07C466340CBULL), 19U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xCEC2A4C893497CE7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x85143E7F3E37D721ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x7ACED762883A3F39ULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x51A107BD4D63ACB8ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x4FEDA405AF9E1450ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xAE56D85204A9E077ULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0xCFA6C1D8B133B4C0ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x2D857457138A6888ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE5F0B6EA37C509F3ULL), 37U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x5520E316F8D3F831ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0x7C52EC61CEE4BC48ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 8U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x81972C69BF06287BULL), 11U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterA, 35U);
            aIngress = aIngress + (RotL64(aOrbiterF, 14U) ^ aOrbiterK);
            aIngress = aIngress + (RotL64(aOrbiterH, 43U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterI, 3U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererA = aWandererA + ((RotL64(aPrevious, 43U) + aOrbiterJ) + RotL64(aOrbiterK, 41U));
            aWandererD = aWandererD ^ (((RotL64(aScatter, 5U) + aOrbiterF) + RotL64(aOrbiterA, 11U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 36U) + aOrbiterI) + RotL64(aOrbiterH, 5U)) + RotL64(aCarry, 19U));
            aWandererI = aWandererI ^ ((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterF, 60U));
            aWandererH = aWandererH + (((RotL64(aPrevious, 57U) + RotL64(aOrbiterK, 21U)) + aOrbiterB) + RotL64(aCarry, 37U));
            aWandererC = aWandererC ^ (((RotL64(aScatter, 51U) + aOrbiterB) + RotL64(aOrbiterF, 27U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererE = aWandererE + ((RotL64(aIngress, 21U) + aOrbiterK) + RotL64(aOrbiterA, 53U));
