    std::uint8_t *aSoilLaneB = pWorkSpace->mSoilLaneB;
    std::uint8_t *aSoilLaneC = pWorkSpace->mSoilLaneC;
    std::uint8_t *aSoilLaneD = pWorkSpace->mSoilLaneD;
