            aWandererJ = aWandererJ + (((RotL64(aCross, 53U) + aOrbiterC) + RotL64(aOrbiterE, 22U)) + RotL64(aCarry, 11U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 39U) + aOrbiterG) + RotL64(aOrbiterI, 43U));
            aWandererK = aWandererK + (((RotL64(aIngress, 35U) + RotL64(aOrbiterJ, 13U)) + aOrbiterI) + RotL64(aCarry, 47U));
