            aIngress = (RotL64(aSoilLaneC[((aIndex + 31164U)) & S_BLOCK1], 47U) ^ RotL64(aSoilLaneA[((aIndex + 27378U)) & S_BLOCK1], 6U));
            aIngress ^= RotL64(pSnowLaneC[((aIndex + 27952U)) & S_BLOCK1], 21U);
