            aOrbiterI = (((aWandererE + RotL64(aIngress, 21U)) + RotL64(aCarry, 19U)) + 0x41D3550447449F18ULL) + aTwistOrbiterAssignSaltD[((aIndex + 6U)) & S_SALT1];
