            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x8DAE7E77E8F127C8ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 10U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x56504A2E44D71C36ULL;
