            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x8EF50880A650B083ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 20U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x6B8E83E29131324AULL;
            aOrbiterB = RotL64((aOrbiterB * 0xF9B0F5E36F7572A9ULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x62122BC5572E51F9ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0xB518AA7F5EA7EC1CULL;
            aOrbiterC = RotL64((aOrbiterC * 0x673BEF2766C85D57ULL), 19U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x5F21CC6E2B3AA7A1ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x8241FDAFCA8731B2ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x21F6C1B906133AEBULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x42FD67D534C5A75DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x13126D9A174F6D77ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xB53CCAEA027D14CDULL), 37U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x60D635714B0C0596ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xAA929E349AD02089ULL;
