            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xC417D056D9073E18ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x3A3D595414888A2FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x242670D783F3F99FULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x8E23930D75D67412ULL;
