            aOrbiterK = ((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 11U)) + 0xBBE60A7DFAE696F2ULL;
            aOrbiterB = ((aWandererB + RotL64(aScatter, 29U)) + RotL64(aCarry, 53U)) + 0x1A362BC4B3D6D10BULL;
            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 42U)) + 0x873820C4A1795C61ULL) + aTwistOrbiterAssignSaltD[((aIndex + 22U)) & S_SALT1];
            aOrbiterE = (aWandererC + RotL64(aScatter, 21U)) + 0x36FA8D5118C6D628ULL;
            aOrbiterF = ((aWandererG + RotL64(aCross, 11U)) + RotL64(aCarry, 27U)) + 0xC7576C4677F79451ULL;
