            aOrbiterA = ((aWandererJ + RotL64(aCross, 47U)) + 0x9587F4E3B296F492ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0xA9FA9BF1845DF14BULL) + aTwistOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
