            aOrbiterF = ((aWandererG + RotL64(aCross, 3U)) + 0xB56F4B85EEDD5C3FULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterD = ((aWandererE + RotL64(aIngress, 29U)) + RotL64(aCarry, 19U)) + 0x21D1B76953149799ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x884EB68847371C20ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x1874BA88E257639FULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 14U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x0B1E2BB03732A17BULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xC7C572C1F7BD526DULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x10B027F32A43CB47ULL;
