            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 37U) ^ RotL64(aCarry, 57U)) + (RotL64(aPrevious, 22U) ^ RotL64(aCross, 5U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterB = (aWandererH + RotL64(aPrevious, 3U)) + 0xE30A22049195CCA9ULL;
            aOrbiterI = ((aWandererE + RotL64(aCross, 58U)) + RotL64(aCarry, 51U)) + 0xA271ABF325EE9DB3ULL;
            aOrbiterK = (aWandererK + RotL64(aScatter, 51U)) + 0x9F02E68CF3935B8FULL;
            aOrbiterH = (((aWandererG + RotL64(aIngress, 29U)) + RotL64(aCarry, 27U)) + 0xC4B376D84AC6438AULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterG = (aWandererI + RotL64(aScatter, 35U)) + 0xE8E84BDF43363515ULL;
            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 19U)) + RotL64(aCarry, 11U)) + 0xE963CA123C4A3C0AULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 17U)) & S_SALT1];
            aOrbiterE = (aWandererB + RotL64(aIngress, 13U)) + 0xD305F215172694E4ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0xAB85B2AD5AE18FA4ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x341C299AC0D5270BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA233A28E43429351ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x0C6EDCA738D147C6ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xFE2A1053D9D4348EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7E67BB2F907A2C09ULL), 51U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0xD2123940FDB94045ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xD1DD1A7C98706495ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x0636BF1DC614CE41ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x1A4C3DDD1625AD6EULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xDE34F730DD9B9C26ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xCDBFA3DB22C8A2E3ULL), 5U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0x6DB357F6428E4FC4ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xBA757DF858373487ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE880FB39F8AAD925ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xA33419E12B6C54D9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x4B4048FD7B468095ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC09221A41C08EB37ULL), 21U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0xDED1DD0D36358940ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x273C74A6C680C232ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x84F85F7B81B69CFDULL), 35U);
            //
            aIngress = RotL64(aOrbiterI, 29U) ^ aOrbiterE;
            aIngress = aIngress + (RotL64(aOrbiterH, 41U) ^ aOrbiterK);
            aIngress = aIngress + (RotL64(aOrbiterB, 3U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterG, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererG = aWandererG + ((RotL64(aCross, 35U) + RotL64(aOrbiterI, 50U)) + aOrbiterB);
            aWandererH = aWandererH ^ (((RotL64(aScatter, 19U) + RotL64(aOrbiterE, 35U)) + aOrbiterI) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 41U) + aOrbiterC) + RotL64(aOrbiterB, 11U)) + RotL64(aCarry, 35U));
            aWandererE = aWandererE ^ ((RotL64(aIngress, 53U) + aOrbiterB) + RotL64(aOrbiterK, 5U));
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 27U) + RotL64(aOrbiterC, 23U)) + aOrbiterH) + aKeyRotateWandererUpdateSaltF[((aIndex + 24U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aCross, 5U) + aOrbiterH) + RotL64(aOrbiterG, 57U));
            aWandererI = aWandererI + (((RotL64(aScatter, 12U) + RotL64(aOrbiterC, 29U)) + aOrbiterG) + RotL64(aCarry, 47U));
