            //
            aOrbiterI = (((aWandererI + RotL64(aIngress, 5U)) + RotL64(aCarry, 51U)) + 0xE91144A09060FD93ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aPrevious, 43U)) + 0x0B67379104F8576FULL;
            aOrbiterA = ((aWandererJ + RotL64(aScatter, 20U)) + RotL64(aCarry, 37U)) + 0xDA0A06769DDB2673ULL;
            aOrbiterK = ((aWandererG + RotL64(aCross, 37U)) + 0xAA31DF77BDEBC744ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
