            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x97CA1C9B9B593191ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x09DB2A8398D8FC0CULL) ^ aKeyRotateOrbiterUpdateSaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x354AFBA043B7019DULL), 13U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xBF34AA91D444949EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0xC80F23103356178BULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x5C983E89AB0A88FDULL), 35U);
