            aOrbiterI = RotL64((aOrbiterI * 0xC516B042D90BBB1DULL), 3U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0xE3EB292E34F80AC9ULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xCF28EA98A2696238ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x50DE20D9635DB55BULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x46BE6439C79FC160ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0xD81BC31406D27709ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x1384ACE0A13B3B7FULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x37D2525E975A4F6AULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xB28675C10984BE34ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xABADD4F29B1AF1ABULL), 57U);
