            aIngress ^= (RotL64(aIceLaneD[((aIndex + 8056U)) & S_BLOCK1], 43U) ^ RotL64(aWoodLaneB[((aIndex + 9725U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseA(aIngress);
