            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 6182U)) & S_BLOCK1], 58U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 7941U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 7269U)) & S_BLOCK1], 11U) ^ RotL64(aHeartLaneA[((aIndex + 6653U)) & S_BLOCK1], 21U));
            aCross = TwistMix64::DiffuseB(aCross);
