            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x1CB4414DAA13BEBBULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xADC50A5235965172ULL) ^ aKeySpawnOrbiterUpdateSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x39FD70F32ED18413ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x37DC645E3B6265C7ULL;
