            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0x2F3F1D425A249742ULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0xF42CA62351664367ULL) ^ aKeySpawnOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
